def requires_access_dag(
    method: ResourceMethod, access_entity: DagAccessEntity | None = None
) -> Callable[[Request, BaseUser], None]:
    def inner(
        request: Request,
        user: GetUserDep,
    ) -> None:
        dag_id: str | None = request.path_params.get("dag_id")

        _requires_access(
            is_authorized_callback=lambda: get_auth_manager().is_authorized_dag(
                method=method, access_entity=access_entity, details=DagDetails(id=dag_id), user=user
            )
        )

    return inner

@router.get(
    "/{task_instance_id}",
    status_code=status.HTTP_200_OK,
)
def get_hitl_detail(
    task_instance_id: UUID,
    session: SessionDep,
) -> HITLDetailResponse:
    ti_id_str = str(task_instance_id)
    hitl_detail_model = session.execute(
        select(HITLDetail).where(HITLDetail.ti_id == ti_id_str),
    ).scalar()
    return HITLDetailResponse.from_hitl_detail_orm(hitl_detail_model)

if self.path_param_name:
